"""Task 7C revision of the existing report's shared editable content model.

Reads saved evidence only. No dataset/model loading, fitting or prediction.
"""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
ML=ROOT/'reports/ml'
OPT=ML/'optimization/task7c0-v1'
AUTHORS='Bilal Malik — 24P-3061; Aun Anis — 24P-3017'
TITLE='Codebase Archaeologist — AI-Powered Repository Intelligence & Defect Risk Analyzer'

def read(path):return json.loads(path.read_text())

def build(g,assets):
    page,para,sub,table=g.page,g.para,g.sub,g.table
    comparison,test,meta,schema=g.COMPARISON,g.TEST,g.META,g.SCHEMA
    results=read(OPT/'results.json'); protocol=read(OPT/'protocol.json')
    def p(b,*items):
        for item in items:para(b,item)
    def t(b,title,heads,rows,widths=None):
        number=len(g.TABLES)+1;g.TABLES.append({'number':number,'title':title})
        para(b,f'Table {number}. {title}');table(b,heads,rows,widths)
    def f(b,path,caption,height=250):
        number=len(g.FIGURES)+1;g.FIGURES.append({'number':number,'title':caption,'path':str(path.relative_to(ROOT))})
        g.figure(b,path,f'Figure {number}. {caption}',height)
    def metrics_rows(source):
        return [[name]+[f'{m[k]:.6f}' for k in g.METRICS] for name,m in source]
    b=page('FM','Authorship and Declaration','Two-member university project · editable academic details')
    p(b,AUTHORS,
      'This report describes the implemented Codebase Archaeologist application and its recorded research experiments. Both named students are the project authors. No individual responsibilities or contribution percentages are assigned. The project team confirms that the instructor permits two members; this is not a claim that an institutional approval certificate was independently inspected.',
      'Scientific declaration. Reported scores come from saved evaluation artifacts. Experimental models are separated from the deployed Random Forest. No new model fitting or test evaluation is performed during document generation. The previously evaluated official test split is exposed historical evidence. No fabricated application screenshot, defect finding or performance gain is included.')
    t(b,'Academic details and confirmation status',['Field','Recorded value / action'],[
      ['Institution','FAST-NUCES, Peshawar — recorded in the previous report; confirm current submission wording.'],
      ['Department / class','Software Engineering (SE) / Class 5A — previous report record; confirm for both authors.'],
      ['Course','[CONFIRM COURSE TITLE AND CODE]'],['Instructor','[CONFIRM INSTRUCTOR NAME]'],
      ['Semester','[CONFIRM SEMESTER]'],['Submission date','[CONFIRM SUBMISSION DATE]'],
      ['Build date','23 November 2026; document-generation date, not an invented submission deadline.']],[.25,.75])
    p(b,'Authorship acknowledgement/signatures: ____________________    ____________________ . These are editable signature spaces, not signed declarations. Academic details above must be confirmed by the team before submission.')

    b=page('FM','Abstract','Repository intelligence with measured scientific limits')
    p(b,'Understanding an unfamiliar repository requires an integrated view of files, functions, dependencies and change history. Codebase Archaeologist combines secure ZIP/public-GitHub ingestion, C and Python structural analysis, evidence-preserving visualizations and C-only machine-learning-assisted defect-risk estimation. FastAPI returns bounded source-free analysis records to a Jinja2/vanilla-JavaScript multi-page workspace. Knowledge Graph, directory-based Architecture, six Heatmap metrics, Blast Radius paths, Jordan Local and Codebase Time Machine support technical investigation without claiming runtime completeness.',
      'The supervised component uses the CodeXGLUE/Devign C-function dataset. Official partitions contain 21,854 training, 2,732 validation and 2,732 test records. Historical cleaning removes 113 development records, retaining 21,750 training and 2,723 validation rows. Eleven numerical syntax/size features feed Logistic Regression, Random Forest and Histogram Gradient Boosting. Random Forest was selected on validation F1 0.520995; its historical, previously exposed official-test F1 is 0.526316 and ROC-AUC 0.587354.',
      'A controlled optimization investigation compared eleven configurations in three grouped training folds and evaluated seven finalists, including an experimental 22-feature representation and Extra Trees. Training-only out-of-fold threshold selection and a predeclared deployment gate produced no justified replacement. Enhanced Random Forest at fixed threshold 0.5 reached validation F1 0.534692 with lower ROC-AUC, insufficient for adoption. The production model and inclusive threshold 0.5 remain unchanged.',
      'Generalization claims are limited by shared projects/commits, lexical similarities, modest discrimination and lack of independent confirmation. An always-positive validation comparator has F1 0.606092 but zero specificity, illustrating why F1 alone is inadequate. Automated application tests substantiate implemented contracts; real-browser/mobile/GPU acceptance and authentic screenshot capture remain separate. This work contributes an auditable engineering workflow and transparent empirical study, not a confirmed-vulnerability detector.')
    sub(b,'Keywords and abbreviations')
    p(b,'Static analysis; repository intelligence; defect-risk estimation; C; Random Forest; reproducibility. AST: abstract syntax tree; CV: cross-validation; OOF: out-of-fold; RF: Random Forest; HGB: Histogram Gradient Boosting; PR/AP: precision–recall/average precision; SHA: Git object identifier; ML: machine learning.')

    b=page('01','Introduction','From source inventory to inspectable engineering evidence')
    p(b,'Understanding an unfamiliar repository starts with concrete questions: which files are present, which languages dominate, where source volume is concentrated, and which relationships should be inspected first? Repository intelligence makes this structure visible. A developer joining a project, a reviewer investigating complexity and a student preparing a demonstration all benefit from consistent measurements and stable navigation. Size alone cannot establish correctness, maintainability quality or security.',
      'Repositories contain several kinds of evidence. Directory structure describes organization; function definitions expose syntax and locations; resolved calls and imports describe observed static dependencies; Git commits describe recorded evolution. Each answers a different question. Collapsing these into a single unexplained score would obscure both the evidence and its limits. The application instead presents separate, connected workspaces with source paths, coverage and relationship explanations.',
      'Machine-learning-assisted defect review addresses a narrower problem: whether a C function exhibits statistical patterns associated with defect-related labels in a research dataset. A learned association may guide review attention, but cannot replace compilation, tests, dataflow reasoning or security review. Structure, rule-based hotspots, historical churn and model estimates are therefore distinct signals. A negative prediction is not a safety guarantee.',
      'The project grew from a bounded ZIP analysis prototype into a multi-page platform. This report revises the earlier Tasks1–3A research document: it retains dataset provenance, preprocessing, original comparison and inference-contract evidence, while adding implemented graph/architecture/impact/history/assistant features and the controlled Task 7C.0 investigation. Product scope is broader than the supervised experiment; extra visual features do not substitute for the university ML requirements.')

    b=page('02','Problem Statement and Objectives','Two analytical levels, explicit outputs')
    p(b,'The repository-level problem is fragmented access to inventory, source structure, dependencies and historical context. The required system safely accepts supported repository input and returns reproducible descriptive records that can be explored without uploading or parsing again on each page. The function-level problem is reproducible binary classification of supported C functions using a real saved model, while exposing partial coverage and uncertainty.',
      'Target users are developers, reviewers and academic demonstrators investigating an unfamiliar codebase. Expected outputs are file/language metrics, structural measurements, inspectable dependency paths, bounded history evidence and genuine C-function model scores. The unit of supervised prediction is a function, never a repository-wide defect probability. Unsupported languages must remain unscored.')
    t(b,'Measurable project objectives',['Objective','Implemented evidence / boundary'],[
      ['Secure intake','ZIP/public GitHub input shares archive/scanning analysis; imported code never executes.'],
      ['Structural intelligence','C Tree-sitter and Python AST metrics, source locations and explainable hotspot rules.'],
      ['Connected investigation','Stable IDs across graph, architecture, heatmaps, impact and local assistant.'],
      ['Reproducible ML','Pinned dataset, explicit cleaning, numeric schema, three original fitted/evaluated candidates.'],
      ['Honest selection','Validation-F1 baseline choice, exposed-test disclosure, multi-metric optimization gate.'],
      ['Usable application','Distinct routes, bounded snapshots, export, error/empty states and reduced-motion handling.']],[.30,.70])
    p(b,'Success means evidence-backed operation and a defensible scientific account, not an arbitrary accuracy target. Automatic code repair, verified exploit detection, dynamic execution tracing and language-general defect prediction are outside the implemented scope.')

    b=page('03','Background and Related Work','Static facts, statistical signals and history')
    p(b,'Static analysis inspects source without running it. Tree-sitter builds concrete syntax trees; the project derives C function definitions, syntax counts and locations from the C grammar. Python AST supplies supported Python structure. Syntax analysis remains incomplete for macros, generated code, dynamic dispatch and unresolved names. The tool records ambiguity instead of turning guesses into confirmed edges. [6]',
      'Devign studies vulnerability identification using graph neural representations. CodeXGLUE provides a broader benchmark including defect detection derived from Devign. This project uses the provider C-function classification data, not the Devign neural architecture or its reported performance. Eleven simple engineered features support lightweight, reproducible classical baselines. Results from different representations, cleaning policies or splits are not directly comparable. [1]–[3]',
      'Random Forest aggregates multiple randomized decision trees. Bagged training samples and random feature subsets reduce dependence among trees; averaged class estimates provide a ranking score. Logistic Regression supplies a scaled linear baseline, while histogram gradient boosting builds successive trees to correct model errors. Extra Trees introduces additional split randomization in the optimization study. None of these methods makes a dataset label equivalent to a verified bug in new code. [4], [5]',
      'Repository graphs and architectural maps are abstractions over observed structure. Here, membership edges organize entities while call/import/include edges carry directed static evidence. Blast Radius reverses dependencies for potential upstream impact, not proof of runtime breakage. Historical churn records change frequency, not developer productivity or defect probability. These interpretations are explicit design decisions grounded in the implementation rather than claims of a new static-analysis algorithm.',
      'Evidence-grounded assistance retrieves actual entities, metrics and paths before answering supported questions. Jordan Local is deterministic intent-aware synthesis, not unrestricted language understanding. Its optional cloud adapter is distinct and consent-gated; live provider validation is deferred. GitHub REST documentation informs history request budgets, caching and cooldown handling. [7], [8]')

    b=page('04','Dataset and Data Description','Pinned CodeXGLUE/Devign evidence')
    p(b,'The recorded source is google/code_x_glue_cc_defect_detection on Hugging Face, revision69bd48c03223c2104342acd9a807caf61ac3efb8. The tracked reports/ml/source_manifest.json pins URLs and SHA-256 checksums. PyArrow reads provider Parquet records directly; remote dataset scripts and source functions are not executed. The actual schema is id:int32, func:string, target:bool, project:string and commit_id:string. [1]–[3]',
      'Raw func is C source text; it is not the numerical feature vector. target supplies the provider binary defect-related class, converted to0/1. Project, commit ID, record ID and labels are excluded from model predictors. The cleaned training source spans FFmpeg and QEMU; historical defect/commit-derived labeling, sampling and project concentration constrain representativeness. This report does not independently relabel source or assert that every positive is an exploitable vulnerability.',
      'The provider declares C-UDA; local acquisition preserves the card/agreement and checksums. This declaration is not blanket rights clearance for upstream source projects or redistribution of raw code. The repository provides acquisition instructions rather than committing the raw dataset. The underlying Devign paper and CodeXGLUE task/card remain the attribution trail. [1]–[3]')
    t(b,'Official and cleaned split counts',['Partition','Official rows','Cleaned rows','Negative / positive'],[
      ['Training','21,854','21,750','11,786 / 9,964'],['Validation','2,732','2,723','1,539 / 1,184'],['Test','2,732','2,732 unchanged','1,477 / 1,255 (historical audit)']],[.22,.20,.23,.35])
    p(b,'Official memberships were retained, not replaced by a favorable random split. Test class counts are retrospective integrity evidence, not development inputs. During optimization only test source/metadata was available to the label-blind similarity audit; no new test predictions were made.')
    f(b,OPT/'development_classes.png','Actual cleaned development class distribution; official test excluded.',330)

    b=page('05','Data Preprocessing','Explicit cleaning and train-fitted transformations')
    p(b,'Development cleaning normalizes CRLF/CR to LF and strips outer whitespace before hashing source. It preserves internal whitespace, comments, identifiers and literals. Missing/invalid source or labels have explicit rejection reasons; raw artifacts are never overwritten. Same-label normalized duplicates retain one deterministic record, and contradictory-label development groups are quarantined rather than majority relabeled. Validation takes precedence over training when an identical retained source occurs in both.',
      'Test source hashes are used without test targets to remove exact development overlap. No official test row is deleted. The saved cleaning audit reproduces113 development removals and54 conflicting-label groups. These are different quantities: a group can contain multiple records and exclusion reasons can overlap. Cleaned normalized exact cross-split overlap is zero under that policy, which does not establish semantic-clone or project/time independence.',
      'Only exactly-one-function valid parses receive structural measurements. There are 4,029 training and463 validation records with missing structural feature values. Original numerical feature order is fixed; the first three lexical measurements remain usable. Missing AST features are NaN, not zero. Median imputation is fitted on training only; Logistic Regression additionally uses a training-fitted StandardScaler. Tree models do not require feature scaling. All predictors are numeric, so categorical encoding is not applicable. Target boolean conversion is label handling, not predictor encoding.',
      'The sklearn Pipeline keeps imputation/scaling inside fitting. In grouped CV a fresh clone is fitted only on each training fold; validation and test never determine medians, scales or model parameters. No oversampling is performed before splitting or on evaluation data. Data imbalance is mild:45.81% positive training and43.48% positive validation. Configuration comparisons include weighted and unweighted variants, but some other hyperparameters co-vary, so they are not isolated causal class-weight ablations.',
      'The later source-shape and shingle audit is reported separately in Chapter 9. It preserves original benchmark membership and adds a conservative diagnostic mask. Similarity findings are not a license to remove difficult evaluation records to improve accuracy.')
    f(b,ML/'missing_and_duplicates.png','Saved original missingness/duplicate audit figure; development cleaning evidence.',260)

    b=page('06','Exploratory Data Analysis','Descriptive analysis of genuine development data')
    p(b,'EDA is performed on cleaned training/validation records and numerical features, not on application heatmaps or test-target distributions. reports/ml/eda_summary.json, observations.txt and saved PNGs provide reproducible evidence. The training distribution is mildly imbalanced; the positive fraction is a dataset prevalence, not the risk of a newly uploaded repository.',
      'Source-size and syntax distributions are heterogeneous. Lexical size, decisions, nesting and call counts describe distinct but related aspects of a function; long-tailed distributions motivate reporting robust summaries rather than assuming every function is typical. Parser abstention means a structural distribution covers measured records only. Missing structural rows remain in model fitting through imputation instead of being silently omitted as hard cases.',
      'The strongest absolute recorded training feature correlation is function_bytes versus nonblank_lines, Pearson r=0.9853. This is consistent with redundant measures of source size. It does not imply that size causes defects or that correlated features are sufficient to predict them. The class-separated plots are descriptive associations, not evidence of separable, cleanly labeled populations.',
      'These findings motivate a compact baseline, train-only transformations and cautious evaluation. The optimization feature additions were syntax/density hypotheses specified before new validation predictions; they were not chosen by examining test correlations. Figure sources and scope remain explicit so a reviewer can distinguish dataset EDA from visual exploration of an arbitrary imported project.')
    f(b,assets/'distributions_selected.png','Selected original EDA panels: physical lines, bytes, decision complexity and calls; cropped from saved distributions.',245)
    f(b,ML/'feature_correlations.png','Original training numerical-feature correlation matrix; association is not causation.',390)

    b=page('07','System Architecture','Shared analysis, scoped workspaces and bounded history')
    p(b,'FastAPI exposes public/import routes and nine real workspace routes. Jinja2 templates share workspace_base.html while feature includes/controllers load only the active view. No large framework or hidden monolithic dashboard is required. product/store.js owns source-free browser snapshots; product/workspace.js restores the active snapshot and initializes the scoped feature. JSON analysis contracts preserve stable entity IDs across navigation.',
      'Both ZIP and GitHub input converge in analyze_archive. A temporary directory contains validated extraction, inventory scanning, C/Python structural parsing, C inference, graph extraction and directory aggregation. Shared parsed-file data avoids redundant parsing where supported. Cleanup removes extracted source after analysis. The response carries metrics, locations, relationship evidence and coverage, not complete repository source bodies.',
      'Knowledge Graph and Architecture are backend evidence products. Blast Radius and Jordan Local reuse the retained graph in bounded frontend indexes, without executing uploaded code or requesting re-ingestion. Time Machine is a separate bounded history retrieval path pinned to the analyzed GitHub revision. It cannot recover Git history from an ordinary source ZIP. Its cached public evidence is not a server-global active repository session.',
      'The current snapshot is selected by an opaque per-tab pointer in sessionStorage. IndexedDB retains at most three origin snapshots, each at most24 MiB and expiring two hours after save. This is browser-profile persistence, not authentication, encryption or cross-origin sharing. Another same-origin script or person with browser-profile access can inspect it. A fourth context can evict an older tab; failed replacement preserves the prior pointer where possible.')
    f(b,assets/'architecture.png','Current implementation architecture; separate source-analysis and pinned-history boundaries.',285)

    b=page('08','ML Methodology','Original supervised study and production contract')
    p(b,'Let x be the ordered numerical measurements of one supported C function and y its provider class. A fitted pipeline estimates a label-1 score s(x). The application assigns predicted class 1 when s(x)>=0.5 and class 0 otherwise. The score is uncalibrated:0.7 is not an established70% real-world defect probability. File/directory maxima aggregate observed function scores and are not new file-level predictions.',
      'The production model version is devign-v1-4a23cc304ca8. The original c-function-v1 schema contains physical_lines, nonblank_lines, function_bytes, parameter_count, conditional_count, loop_count, return_count, max_nesting_depth, decision_complexity, pointer_syntax_count and call_count. Definitions and edge cases are in AppendixA. Shared extract_features/feature_matrix code and strict metadata ensure identical ordering during training and live inference. Invalid functions abstain rather than generating substitute scores.',
      'Three original sklearn pipelines use seed 42. Logistic Regression uses median imputation, StandardScaler, C=1, balanced weights and lbfgs. Random Forest uses median imputation,200 trees, depth 12, minimum leaf 3, sqrt feature subsampling and balanced weights. Histogram Gradient Boosting uses imputation, learning rate0.08,160 iterations,15 leaves, minimum leaf 20, L2=1, balanced weights and no early stopping. Saved configurations, versions and checkpoint hashes are evidence of actual fitting.',
      'All three original models were trained and evaluated on the same cleaned validation split. Random Forest was selected by highest validation F1 before the selected pipeline was evaluated once in the original final-test workflow. Only Random Forest has the saved final official-test evaluation; claiming all three have final-test metrics would be false. The already viewed test is now exposed historical evidence, not a new blind confirmation.',
      'Accuracy measures total correctness, precision the fraction of predicted positives that are positive, recall the fraction of positives retrieved, and F1 their harmonic mean. ROC-AUC measures ranking over thresholds; average precision summarizes the precision–recall curve. Confusion counts expose false positives/negatives. These metrics answer different questions; threshold and prevalence must accompany F1 interpretation. [4], [5]')
    f(b,assets/'training.png','Original training/selection and later optimization boundaries; no new test evaluation.',265)

    b=page('09','ML Optimization Investigation','Controlled development, not test-set score chasing')
    p(b,'Task 7C.0 investigated whether reproducible lightweight changes justified replacing the deployed model. Before fitting, it locked one seed, eleven configurations, three training-only grouped folds, seven maximum family/schema finalists, a fixed threshold grid and a combined deployment gate. A900-second cooperative budget, one sklearn/BLAS worker and finite tree/iteration settings constrained work. The completed run took186.522 seconds:53.897 for feature/setup work and132.020 for fitting, validation, serialization and gates.',
      'The dataset audit found1,816 validation rows sharing a project/commit pair with training,233 sharing normalized token shape and at least 554 verified shingle similarities. Counts overlap and must not be summed. Token shape normalizes identifiers/literals while retaining keywords/operators and ignoring comments; equal shape is not semantic equivalence. Near retrieval uses bottom24 five-token shingle hashes, skips postings above 64, checks at most50 candidates/query and verifies Jaccard>=0.85. Search caps mean the near counts are lower bounds.',
      'A label-independent conservative diagnostic excludes validation rows matching training project/commit, token shape or confirmed approximate similarities, retaining 794 rows (347 negative/447 positive). It is a shifted subset of the same validation data, not an independent test. Training groups transitively join project/commit pairs and exact token shapes, yielding10,177 groups with largest group1,191 rows. StratifiedGroupKFold keeps them disjoint. Approximate clones are not exhaustively grouped, and shared projects remain.')
    t(b,'Overlap diagnostics and interpretation',['Diagnostic','Validation rows','Interpretation'],[
      ['Shared project/commit','1,816','Related origins; not proof every row is a leaked clone.'],
      ['Shared normalized token shape','233','Conservative lexical structure; semantics may differ.'],
      ['Verified near-shingle match','At least 554','Bounded retrieval; not exhaustive semantic clone detection.'],
      ['Diagnostic retained','794 of 2,723','Different prevalence; no independent holdout claim.']],[.32,.18,.50])
    sub(b,'Experimental representation and search')
    p(b,'The experimental c-function-v2-experimental schema appends11 parser-derived counts/densities to the unchanged original11. AppendixA lists them. All 24,473 development rows pass original-feature-prefix equality, including NaNs. Source-only extraction is shared by cache generation and offline candidate input, with no labels or origin metadata among predictors. The strict production loader never silently accepts this experimental version.',
      'Eleven fixed configurations explore LR regularization/weights, RF depth/leaf/features/weights, HGB iterations/leaves/regularization and Extra Trees160/depth 16/leaf 4/balanced. Each receives three training-only CV fits. Maximum mean fold F1 at 0.5 shortlists one per family/schema before validation, yielding seven full-training fits. This is a bounded manual configuration search, not an exhaustive optimum. Some parameters co-vary, so individual causes cannot be attributed.')
    f(b,assets/'cv_print.png','Training-only grouped three-fold mean F1 at 0.5; bars show fold SD, not confidence intervals. Label suffix11/22 denotes feature count.',280)
    sub(b,'Threshold selection and deployment gate')
    p(b,'OOF predictions alone select thresholds from0.30,0.35,...,0.70. The unconstrained F1 optimum is reported; an operating rule requires OOF precision>=0.50 and recall>=0.20, otherwise falling back to0.5. No validation/test threshold tuning occurs. Low unconstrained thresholds often favor near-all-positive predictions, so an apparent F1 increase needs discrimination and specificity context.',
      'The predeclared gate requires validation F1 gain>=0.02, positive lower95% paired cluster-bootstrap delta, precision>=0.50, ROC-AUC no worse, accuracy within0.01 of baseline, balanced accuracy no worse and nonnegative F1 difference on at least 300 purged rows. It also bounds artifact size16 MiB and measured batch prediction latency to25ms/function and2× baseline. Passing those numerical checks would still require versioned loader, C-only integration, parity and rollback acceptance.',
      'Seven finalists are measured once on full validation and the diagnostic subset. Two hundred paired validation-cluster bootstrap resamples (seed 42) describe development uncertainty, not independent confirmation or multiplicity-adjusted significance. Five warm prediction batches measure local pipeline inference excluding AST extraction; they are not end-to-end browser latency. All candidates reload with exact probabilities on the first10 validation rows. No new test predictions or external evaluation dataset are introduced.')
    f(b,assets/'threshold_print.png','Training OOF threshold/F1 tradeoffs; marked operating choices were fixed before validation.',275)

    b=page('10','Evaluation and Results','Modest discrimination and defensible model retention')
    p(b,'Table below preserves the original candidate comparison on cleaned official validation (n=2,723). Figures are numerical evidence from saved artifacts, rounded here to six decimals; exact machine-readable values remain in reports/ml. Validation scores are not training scores or final-test results. Random Forest has the highest original candidate F1 and ROC-AUC, but those values do not establish excellent predictive performance.')
    t(b,'Original candidate validation metrics, threshold 0.5',['Model','Accuracy','Precision','Recall','F1','ROC-AUC'],metrics_rows([(n.replace('_',' '),x['validation']) for n,x in comparison.items()]),[.30,.14,.14,.14,.14,.14])
    p(b,'The selected RF historical test (n=2,732) has accuracy 0.555271, precision 0.515267, recall 0.537849, F1 0.526316 and ROC-AUC 0.587354. Confusion counts are TN 842, FP 635, FN 580, TP 675. These are genuine saved values from the previously exposed test; they were not recalculated to select experimental models. Generalization beyond the source projects and label process remains unproven.')
    selected=[('Original RF / .50',results['baseline_validation']),('Enhanced RF / .50',results['finalists']['v2_rf_baseline_shape']['validation_at_half']),('Enhanced RF / .55',results['finalists']['v2_rf_baseline_shape']['validation']),('Extra Trees / .50',results['finalists']['v2_extra_trees']['validation']),('Always positive',results['always_positive_validation'])]
    t(b,'Selected optimization comparisons on reused official validation',['Model / threshold','Accuracy','Precision','Recall','F1','ROC-AUC'],metrics_rows(selected),[.30,.14,.14,.14,.14,.14])
    p(b,'Enhanced RF at fixed0.5 gains F1 0.013698 but lowers accuracy and ROC-AUC, and misses the predefined0.02 improvement requirement. At OOF-selected0.55 it sharply reduces recall/F1. Extra Trees is the strongest new finalist under the operating-threshold protocol (F1 0.506073), below original RF; its paired F1-delta interval [-0.036261,0.006065] includes zero. No candidate passes the gate. All seven finalists and all eleven CV configurations remain published, not only favorable examples.')
    f(b,assets/'validation_print.png','Reused validation: fixed0.5 and OOF-operating F1 alongside ROC-AUC; no new test results.',295)
    sub(b,'Trivial comparators and scientific interpretation')
    p(b,'Always-positive validation F1 is 0.606092, higher than RF F1, with precision 0.434815, recall 1, zero specificity and ROC-AUC 0.5. Majority-negative accuracy is 0.565185 with F1 zero. RF accuracy 0.568491 is only slightly above the majority comparator. These facts prevent claims of universal baseline superiority or strong practical defect identification. F1 ignores true negatives and rewards recall differently depending on prevalence; ranking, specificity, balanced accuracy and review workload also matter.',
      'On the794-row diagnostic, original RF F1 is 0.574610 but ROC-AUC only0.526178. Different prevalence affects F1, and the subset cannot be compared as a new independent benchmark. Extra Trees improves diagnostic F1 to0.596567 but has weaker full-validation results. Preserving the original model is a defensible bounded decision, not proof it is globally optimal. The investigation supports restraint rather than an advertised performance improvement.')
    f(b,assets/'precision_recall_print.png','Actual validation precision/recall operating points; not full curves. Original ROC/PR curves remain in reports/ml/optimization/task7c0-v1/validation_curves.png.',290)
    f(b,OPT/'validation_confusions.png','Validation confusion matrices: original RF and the strongest new operating-threshold finalist; candidate not deployed.',225)

    b=page('11','Application Implementation','Real user workflows and evidence navigation')
    p(b,'A user enters /explore and chooses a ZIP or public GitHub URL. GitHub intake validates owner/repository URLs, resolves a snapshot and downloads a bounded archive; it does not clone or retain .git. Both paths invoke the same extraction and analysis pipeline. Import progress is indeterminate when the server exposes no granular stages; no artificial percentage is reported. Overview displays real inventory and coverage after a successful analysis.',
      'Risk exposes genuine C model scores, search/sort/details and unscored states. Structure lists C/Python functions, span, decisions, loops, nesting and rule-based hotspot reasons. Neither a structural hotspot nor a current model score is a confirmed bug. Missing model artifacts leave other analysis usable; trusted loading validates feature order, parser/numerical versions, classes and checksums. Navigation and export reuse returned results rather than re-running inference.',
      'Knowledge Graph presents repository hierarchy, resolved calls and import/include dependencies in2D/3D. Stable node IDs connect selection, filters, relationship evidence and cross-feature navigation. Architecture partitions files by immediate parent directory, with explicit root-file grouping; it does not invent service layers. Directed aggregates retain original edge types/evidence. Dependency strongly-connected groups use retained imports/includes and can overapproximate file-level cycles.',
      'Heatmaps support physical lines, function count, maximum complexity, hotspot count, bytes and maximum observed C-function score. Directory drill-down and breadcrumbs preserve hierarchy; true zero, unavailable, unsupported and unscored values are distinguished. Maximum function score is not a directory probability. Blast Radius uses directed resolved relationships,1–3 hops, deterministic representative paths and bounded cycle-safe traversal. Membership seeds entities but does not prove propagation.',
      'Jordan Local answers supported intent-aware questions using lexical entity resolution, structural/risk facts and graph/impact paths. Ambiguous names produce candidates rather than an arbitrary selection. Bounded conversation is snapshot-scoped; no full function bodies are retained for explanation. The existing optional cloud adapter requires configuration and explicit disclosure/consent, but live provider activation and testing are outside this submission verification. No cloud service is needed for Local mode.',
      'Codebase Time Machine retrieves real GitHub REST history pinned to the analyzed SHA, normally24 commits, with explicit coverage. Timeline, activity, churn, comparison and evolution operate on actual retained facts. Timeline orders committer dates separately from upstream commit-list ordering. Comparison uses exact base/head trees, unique identical-blob rename detection and bounded SequenceMatcher text diffs, not new historical complexity/ML analysis. Source ZIPs show no-history rather than invented commits.',
      'JSON export preserves analyzed facts and coverage. IndexedDB restores source-free snapshots across workspace documents without re-ingestion. Full source, archives, credentials and transient comparison patches are excluded from browser snapshots. Explicit expiry/forget/replacement behavior bounds retention, but the browser profile is not a secure multi-user vault.')
    t(b,'Workspace routes and implemented scopes',['Route suffix','Purpose'],[[k,v] for k,v in [('overview','Inventory, provenance and coverage'),('risk','C-only model-estimated review signals'),('structure','C/Python structural metrics and hotspots'),('graph','Hierarchy/calls/dependencies;2D/3D'),('architecture','Directory component aggregates and evidence'),('heatmaps','Six metric views and nested drill-down'),('blast-radius','Potential upstream/downstream reachability'),('jordan','Local evidence-backed investigations'),('time-machine','Pinned real history, diff and revision trees')]], [.28,.72])
    sub(b,'Application screenshot evidence')
    captures=read(ROOT/'submission/screenshots.json')
    for item in captures:
        path=(ROOT/item['path']).resolve()
        if not path.is_relative_to(ROOT/'docs/screenshots'):raise ValueError('Screenshot must be in docs/screenshots')
        if item.get('verified') and not path.is_file():raise FileNotFoundError('Verified screenshot is missing')
        if item.get('verified'):
            if not all(item.get(k) for k in ['captured_at','repository','revision_or_fixture','browser','viewport','captured_by']):raise ValueError('Incomplete screenshot provenance')
